import math

def check_power_of_2(k):
    return k > 0 and (k & (k - 1) == 0)

def solve_case():
    max_A = 10
    solutions = []

    print(f"Checking A from 2 to {max_A}...")

    for A in range(2, max_A + 1):
        limit_m = int(math.sqrt(2**A - 1))

        print(f"--- A = {A} (Max m = {limit_m}) ---")

        for m in range(1, limit_m + 1):
            # Eq 1: m^2 + n = 2^A
            n = 2**A - m**2

            if n <= 0:
                # Should not happen given how limit_m is set, but safer to check
                continue

            # Eq 2: m + n^2 = 2^B
            target_B = m + n**2

            if check_power_of_2(target_B):
                B = int(math.log2(target_B))

                # Requirement: B >= 2
                if B >= 2:
                    solutions.append((m, n, 2, B)) # (m, n, p, B)
                    print(f"Solution found for A={A}: m={m}, n={n}. m+n^2 = {target_B} = 2^{B}.")
                # else:
                    # print(f"Not B>=2 for A={A}, m={m}. m+n^2 = {target_B} = 2^{B}.")

    return solutions

solutions = solve_case()
print("\n--- Summary ---")
print(f"Total solutions found for A <= 10: {len(solutions)}")
if solutions:
    for sol in solutions:
        print(f"Solution: m={sol[0]}, n={sol[1]}, p=2, B={sol[3]}")
else:
    print("No solutions found in the checked range.")

import math

def is_power_of_prime(N, p):
    """Checks if N is a power of p, and if so, returns the exponent A."""
    if N <= 0 or p <= 1:
        return None

    A = 0
    temp_N = N
    while temp_N > 1 and temp_N % p == 0:
        temp_N //= p
        A += 1

    if temp_N == 1:
        # The problem requires A >= 2 (log_p(...) > 1)
        return A if A >= 2 else None
    else:
        return None

def search_solutions(M_max, N_max, primes):
    solutions = []
    for p in primes:
        for m in range(1, M_max + 1):
            for n in range(1, N_max + 1):

                # Check m^2 + n = p^A, A >= 2
                X = m**2 + n
                A = is_power_of_prime(X, p)

                if A is not None:
                    # Check m + n^2 = p^B, B >= 2
                    Y = m + n**2
                    B = is_power_of_prime(Y, p)

                    if B is not None:
                        solutions.append((m, n, p))

    return solutions

M_MAX = 20
N_MAX = 20
TARGET_PRIMES = [5, 7]

found_triples = search_solutions(M_MAX, N_MAX, TARGET_PRIMES)

print(f"Found triples for p=5 or p=7: {found_triples}")
